import * as wt from 'node:worker_threads';

async function main(): Promise<void> {
  const attempt1 = async (): Promise<void> => { try { await wt.postMessageToThread(0, 1); console.log('same thread', 'resolved', undefined); } catch (e: any) { console.log('same thread', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt1();
  const attempt2 = async (): Promise<void> => { try { await wt.postMessageToThread(99, 1); console.log('unknown id', 'resolved', undefined); } catch (e: any) { console.log('unknown id', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt2();
  const bare = new wt.Worker(`
    const wt = require('node:worker_threads');
    const keep = setInterval(() => {}, 1000);
    wt.parentPort.postMessage('bare ready');
  `, { eval: true });
  await new Promise<void>((resolve: () => void): void => { bare.once('message', (m: any) => { resolve(); }); });
  const attempt3 = async (): Promise<void> => { try { await wt.postMessageToThread(bare.threadId, 'x'); console.log('no listener', 'resolved', undefined); } catch (e: any) { console.log('no listener', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt3();
  const thrower = new wt.Worker(`
    const wt = require('node:worker_threads');
    const keep = setInterval(() => {}, 1000);
    process.on('workerMessage', () => { throw new Error('boom'); });
    wt.parentPort.postMessage('thrower ready');
  `, { eval: true });
  await new Promise<void>((resolve: () => void): void => { thrower.once('message', (m: any) => { resolve(); }); });
  const attempt4 = async (): Promise<void> => { try { await wt.postMessageToThread(thrower.threadId, 'x'); console.log('listener throws', 'resolved', undefined); } catch (e: any) { console.log('listener throws', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt4();
  const busy = new wt.Worker(`
    const wt = require('node:worker_threads');
    const keep = setInterval(() => {}, 1000);
    process.on('workerMessage', () => {});
    wt.parentPort.postMessage('busy started');
    const end = Date.now() + 600; while (Date.now() < end) {}
  `, { eval: true });
  await new Promise<void>((resolve: () => void): void => { busy.once('message', (m: any) => { resolve(); }); });
  const attempt5 = async (): Promise<void> => { try { await wt.postMessageToThread(busy.threadId, 'x', [], 50); console.log('timeout', 'resolved', undefined); } catch (e: any) { console.log('timeout', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt5();
  await bare.terminate();
  await thrower.terminate();
  await busy.terminate();
  console.log('done');
}
